import{_ as n,C as s,o as e,c as d,a2 as o,j as i,E as t,a as l}from"./chunks/framework.Dsdg6H41.js";const B=JSON.parse(`{"title":"19-dars (Mentor). Kiberxavfsizlik va shaxsiy ma’lumotlarni himoya qilish asoslari","description":"","frontmatter":{"title":"19-dars (Mentor). Kiberxavfsizlik va shaxsiy ma’lumotlarni himoya qilish asoslari","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"mentor_dars","dars":{"sinf":{"name":"8-sinf (Foundation)","link":"/mentor/8-sinf-cs/"},"week":{"n":7,"link":"/mentor/8-sinf-cs/hafta-07/"},"g":19,"title":"Kiberxavfsizlik va shaxsiy ma’lumotlarni himoya qilish asoslari","lead":"Internet — cheksiz bilim va imkoniyatlar maydoni, ammo unda ehtiyotkor bo'lish zarur. Bugun shaxsiy ma'lumotlaringizni, parollaringizni va qurilmalaringizni kiberxavflardan qanday himoya qilishni o'rganamiz.","slide":"/slaydlar/8-sinf-cs/hafta-07/dars-1.html","test":"/slaydlar/8-sinf-cs/hafta-07/dars-1-test.html","student_link":"/8-sinf-cs/hafta-07/dars-1","tabs":[{"g":19,"link":"/mentor/8-sinf-cs/hafta-07/dars-1","current":true},{"g":20,"link":"/mentor/8-sinf-cs/hafta-07/dars-2","current":false},{"g":21,"link":"/mentor/8-sinf-cs/hafta-07/dars-3","current":false}],"prev":null,"next":{"g":20,"title":"Algoritm tushunchasi va algoritmik fikrlash","link":"/mentor/8-sinf-cs/hafta-07/dars-2"}}},"headers":[],"relativePath":"mentor/8-sinf-cs/hafta-07/dars-1.md","filePath":"mentor/8-sinf-cs/hafta-07/dars-1.md"}`),h={name:"mentor/8-sinf-cs/hafta-07/dars-1.md"},m={class:"blk"},g={id:"darsning-maqsadi",tabindex:"-1"},u={class:"blk"},k={id:"kutiladigan-natija",tabindex:"-1"},y={class:"blk"},v={id:"kerakli-jihozlar",tabindex:"-1"},b={class:"blk"},f={id:"dars-rejasi-80-daqiqa",tabindex:"-1"},q={class:"blk"},z={id:"konspekt-mentor-aytadigan-matn",tabindex:"-1"},c={class:"blk"},x={id:"amaliy-topshiriqlar-va-yechimlar",tabindex:"-1"},p={class:"blk"},_={id:"tezkor-nazorat-savollari",tabindex:"-1"},T={class:"blk"},j={id:"uyga-vazifa",tabindex:"-1"};function P(A,a,S,I,F,K){const r=s("Icon");return e(),d("div",null,[a[25]||(a[25]=o("<p><strong>Fan:</strong> Computer Science Foundation<br><strong>Sinf:</strong> 8-sinf<br><strong>Hafta:</strong> 7-hafta, 1-dars (umumiy 19-dars)<br><strong>Davomiyligi:</strong> 80 daqiqa<br><strong>Bob:</strong> II-bob. Zamonaviy IT yo‘nalishlari va raqamli infratuzilma asoslari (Yakuniy dars)<br><strong>Manba:</strong> O&#39;quv dasturi, II-bob: «Kiberxavfsizlik va shaxsiy ma’lumotlarni himoya qilish asoslari. Kiberxavfsizlik tushunchasi va asosiy xavf turlari. Shaxsiy ma’lumotlar, raqamli iz va maxfiylikni himoya qilish. Kuchli parol yaratish, 2FA va akkaunt xavfsizligi. Phishing, zararli havolalar va ijtimoiy muhandislikdan saqlanish. Qurilma, internet va bulutli xizmatlardan xavfsiz foydalanish.»</p><hr>",2)),i("div",m,[i("h2",g,[t(r,{name:"file-text"}),a[0]||(a[0]=l(" Darsning maqsadi ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#darsning-maqsadi","aria-label":'Permalink to "<Icon name="file-text" /> Darsning maqsadi"'},"​",-1))]),a[2]||(a[2]=i("p",null,"O'quvchilarga kiberxavfsizlik asoslari, asosiy kiberxavflar (fishing, zararli dasturlar, ijtimoiy muhandislik), raqamli iz va shaxsiy ma'lumotlar maxfiyligini tushuntirish; kuchli parol tuzish, 2FA (ikki bosqichli tekshiruv) yoqish hamda internetda xavfsiz ishlash ko'nikmalarini amalda shakllantirish.",-1))]),i("div",u,[i("h2",k,[t(r,{name:"file-text"}),a[3]||(a[3]=l(" Kutiladigan natija ",-1)),a[4]||(a[4]=i("a",{class:"header-anchor",href:"#kutiladigan-natija","aria-label":'Permalink to "<Icon name="file-text" /> Kutiladigan natija"'},"​",-1))]),a[5]||(a[5]=i("ul",null,[i("li",null,"Kiberxavfsizlik nima ekanini va asosiy xavf turlarini (Malware, Phishing, Ransomware) ajrata oladi;"),i("li",null,"Raqamli iz (Digital Footprint) nima ekanini tushunadi va o'zining shaxsiy ma'lumotlarini himoya qila oladi;"),i("li",null,"Kuchli va xavfsiz parol mezonlarini biladi, parollar menejeri va 2FA ning ahamiyatini tushuntiradi;"),i("li",null,"Fishing xabarlari, soxta havolalar va ijtimoiy muhandislik hiylalarini amaliy misollarda fosh etadi;"),i("li",null,"Ommaviy Wi-Fi va internet xizmatlaridan xavfsiz foydalanishning 5 ta oltin qoidasini amalda qo'llaydi.")],-1))]),i("div",y,[i("h2",v,[t(r,{name:"file-text"}),a[6]||(a[6]=l(" Kerakli jihozlar ",-1)),a[7]||(a[7]=i("a",{class:"header-anchor",href:"#kerakli-jihozlar","aria-label":'Permalink to "<Icon name="file-text" /> Kerakli jihozlar"'},"​",-1))]),a[8]||(a[8]=i("ul",null,[i("li",null,"Kompyuter va proyektor (slaydlar namoyishi uchun)"),i("li",null,"Brauzer (parol mustahkamligini tekshirish simulyatori yoki matnli mashqlar uchun)"),i("li",null,"O'quvchi daftari va qalam")],-1)),a[9]||(a[9]=i("hr",null,null,-1))]),i("div",b,[i("h2",f,[t(r,{name:"file-text"}),a[10]||(a[10]=l(" Dars rejasi (80 daqiqa) ",-1)),a[11]||(a[11]=i("a",{class:"header-anchor",href:"#dars-rejasi-80-daqiqa","aria-label":'Permalink to "<Icon name="file-text" /> Dars rejasi (80 daqiqa)"'},"​",-1))]),a[12]||(a[12]=o('<table tabindex="0"><thead><tr><th>Vaqt</th><th>Bosqich</th><th>Mazmun</th></tr></thead><tbody><tr><td>00–08</td><td>Takrorlash</td><td>18-dars (Zamonaviy IT yo&#39;nalishlari: Cybersecurity roli)</td></tr><tr><td>08–25</td><td>Yangi mavzu 1</td><td>Kiberxavfsizlik, raqamli iz va asosiy kiberxavflar (Malware, Fishing)</td></tr><tr><td>25–40</td><td>Yangi mavzu 2</td><td>Akkaunt xavfsizligi: kuchli parol, parollar menejeri va 2FA</td></tr><tr><td>40–45</td><td>Tanaffus</td><td>Qisqa dam olish va savol-javob</td></tr><tr><td>45–60</td><td>Yangi mavzu 3</td><td>Ijtimoiy muhandislik, ommaviy Wi-Fi xavfi va qurilma gigiyenasi</td></tr><tr><td>60–75</td><td>Amaliyot</td><td>3 ta amaliy keys: fishingni aniqlash, parol tekshiruvi, xavfsizlik auditi</td></tr><tr><td>75–80</td><td>Xulosa</td><td>Tezkor nazorat savollari, darsni baholash, uyga vazifa</td></tr></tbody></table><hr>',2))]),i("div",q,[i("h2",z,[t(r,{name:"file-text"}),a[13]||(a[13]=l(" Konspekt (mentor aytadigan matn) ",-1)),a[14]||(a[14]=i("a",{class:"header-anchor",href:"#konspekt-mentor-aytadigan-matn","aria-label":'Permalink to "<Icon name="file-text" /> Konspekt (mentor aytadigan matn)"'},"​",-1))]),a[15]||(a[15]=o('<h3 id="_1-kiberxavfsizlik-nima-va-asosiy-xavflar" tabindex="-1">1. Kiberxavfsizlik nima va asosiy xavflar <a class="header-anchor" href="#_1-kiberxavfsizlik-nima-va-asosiy-xavflar" aria-label="Permalink to &quot;1. Kiberxavfsizlik nima va asosiy xavflar&quot;">​</a></h3><p>Biz har kuni internetdamiz: ijtimoiy tarmoqlar, Telegram, o&#39;yinlar, Google qidiruv, onlayn darslar. <strong>Kiberxavfsizlik (Cybersecurity)</strong> — bu kompyuterlar, smartfonlar, serverlar, tarmoqlar va ulardagi ma&#39;lumotlarni ruxsatsiz kirish, o&#39;g&#39;irlanish yoki zararlanishdan himoya qilish tizimidir.</p><p>Internetda qoldirgan har bir harakatimiz — ko&#39;rgan videolarimiz, qoldirgan izohlarimiz, kiritgan ma&#39;lumotlarimiz <strong>raqamli iz (Digital Footprint)</strong> deb ataladi. Raqamli iz 2 xil bo&#39;ladi:</p><ul><li><strong>Faol iz:</strong> O&#39;zimiz bilib joylagan postlar, fotosuratlar, ro&#39;yxatdan o&#39;tish anketalari.</li><li><strong>Nofaol iz:</strong> Brauzer tarixi, cookie fayllar, IP-manzil, tashrif buyurilgan saytlar.</li></ul><p>Asosiy kiberxavflar:</p><ol><li><strong>Zararli dasturlar (Malware):</strong><ul><li><strong>Virus va Worm:</strong> Fayllarni buzuvchi va o&#39;zini ko&#39;paytiruvchi kodlar.</li><li><strong>Spyware (ayg&#39;oqchi dastur):</strong> Siz tergan klaviatura tugmalarini, parollaringizni yashirincha yozib oluvchi dastur.</li><li><strong>Ransomware (tovlamachi dastur):</strong> Kompyuterdagi barcha fayllarni shifrlab qulflaydi va ochish uchun pul talab qiladi.</li></ul></li><li><strong>Phishing (Fishing — «baliq ovi»):</strong> Firibgarlarning sizga mashhur tashkilot (masalan, Google, Telegram, bank) nomidan soxta xabar yoki havola yuborib, login va parolingizni o&#39;g&#39;irlash usuli.</li></ol><h3 id="_2-akkaunt-xavfsizligi-kuchli-parol-va-2fa" tabindex="-1">2. Akkaunt xavfsizligi: Kuchli parol va 2FA <a class="header-anchor" href="#_2-akkaunt-xavfsizligi-kuchli-parol-va-2fa" aria-label="Permalink to &quot;2. Akkaunt xavfsizligi: Kuchli parol va 2FA&quot;">​</a></h3><p>Har qanday himoyaning birinchi eshigi — <strong>parol</strong>. Ko&#39;pchilik o&#39;quvchilar «123456», «qwerty», «parol123» yoki o&#39;z tug&#39;ilgan yilini qo&#39;yishadi. Bunday parollar <strong>Brute-Force (kuch bilan tanlash)</strong> hujumi orqali 1 soniyada buziladi!</p><p><strong>Kuchli parol mezonlari:</strong></p><ul><li>Kamida <strong>12 ta belgidan</strong> iborat bo&#39;lishi;</li><li>Katta harflar (<code>A-Z</code>), kichik harflar (<code>a-z</code>), raqamlar (<code>0-9</code>) va maxsus belgilar (<code>!@#$%^&amp;*</code>) aralashmasi;</li><li>Shaxsiy ma&#39;lumotlar (ism, familiya, tug&#39;ilgan yil, telefon raqam) bo&#39;lmasligi;</li><li>Har bir sayt yoki akkaunt uchun <strong>alohida (takrorlanmas)</strong> parol qo&#39;yish.</li></ul><blockquote><p><strong>Parollar menejeri (Password Manager):</strong> 50 xil murakkab parolni yodda tutish qiyin. Buning uchun maxsus xavfsiz hamyonlar (Bitwarden, 1Password, Google Password Manager) ishlatiladi. Siz faqat bitta bosh parolni (Master Password) eslab qolasiz.</p></blockquote><p><strong>Ikki bosqichli autentifikatsiya (2FA — Two-Factor Authentication):</strong> Bu akkauntga kirishda paroldan tashqari ikkinchi isbot so&#39;rash usulidir:</p><ol><li><strong>1-omil:</strong> Siz biladigan narsa — parolingiz.</li><li><strong>2-omil:</strong> Sizda bor bo&#39;lgan narsa — telefoningizga kelgan 6 xonali SMS-kod yoki maxsus ilova (Google Authenticator) generatsiya qilgan kod. <em>Natija:</em> Agar tajovuzkor parolingizni bilib olgan taqdirda ham, telefoningizdagi 2-kod bo&#39;lmasa, akkauntingizga kira olmaydi!</li></ol><h3 id="_3-ijtimoiy-muhandislik-va-ommaviy-tarmoqlar-xavfsizligi" tabindex="-1">3. Ijtimoiy muhandislik va ommaviy tarmoqlar xavfsizligi <a class="header-anchor" href="#_3-ijtimoiy-muhandislik-va-ommaviy-tarmoqlar-xavfsizligi" aria-label="Permalink to &quot;3. Ijtimoiy muhandislik va ommaviy tarmoqlar xavfsizligi&quot;">​</a></h3><p>Kiberjinoyatchilar ko&#39;pincha kompyuterni emas, <strong>inson ruhiyatini</strong> aldashadi. Bu <strong>ijtimoiy muhandislik (Social Engineering)</strong> deyiladi:</p><ul><li>Qo&#39;rquv uyg&#39;otish: «Akkauntingiz 1 soatda o&#39;chiriladi, darhol parolingizni yangilang!»</li><li>Qiziqtirish: «Siz 1 000 000 so&#39;m yutib oldingiz, olish uchun bu havola ustiga bosing!»</li><li>Shoshiltirish: «Faqat bugun bepul Telegram Premium, shoshiling!»</li></ul><p><strong>Xavfsiz internetning oltin qoidalari:</strong></p><ol><li>Notanish odamlardan kelgan fayl va havolalarni aslo ochmang (<code>.exe</code>, <code>.scr</code>, <code>.apk</code>, <code>.bat</code>).</li><li>Har doim sayt manzilini (URL) diqqat bilan o&#39;qing: <code>telegram.org</code> o&#39;rniga <code>telegraam-security.com</code> bo&#39;lishi mumkin. Sayt manzili boshida qulf belgisi va <code>https://</code> bo&#39;lishi shart.</li><li>Ommaviy bepul Wi-Fi tarmoqlarida (kafe, vokzal, park) muhim akkauntlarga kirmang va to&#39;lovlarni amalga oshirmang (chunki ommaviy Wi-Fi trafigini ushlab olish mumkin).</li><li>Operatsion tizim va antivirus dasturini doimiy ravishda yangilang (Update).</li><li>Muhim fayllaringizning zaxira nusxasini (Backup) bulutda yoki alohida fleshkada saqlang.</li></ol><hr>',19))]),i("div",c,[i("h2",x,[t(r,{name:"file-text"}),a[16]||(a[16]=l(" Amaliy topshiriqlar va yechimlar ",-1)),a[17]||(a[17]=i("a",{class:"header-anchor",href:"#amaliy-topshiriqlar-va-yechimlar","aria-label":'Permalink to "<Icon name="file-text" /> Amaliy topshiriqlar va yechimlar"'},"​",-1))]),a[18]||(a[18]=o('<h3 id="_1-topshiriq-parol-mustahkamligini-tekshirish-va-kuchli-parol-yaratish-oson" tabindex="-1">1-topshiriq: Parol mustahkamligini tekshirish va kuchli parol yaratish (Oson) <a class="header-anchor" href="#_1-topshiriq-parol-mustahkamligini-tekshirish-va-kuchli-parol-yaratish-oson" aria-label="Permalink to &quot;1-topshiriq: Parol mustahkamligini tekshirish va kuchli parol yaratish (Oson)&quot;">​</a></h3><p>Quyidagi parollarning xavfsizlik darajasini tahlil qiling va 1 ta namunaviy kuchli parol tuzing:</p><ul><li><code>alisher2010</code></li><li><code>qwerty123</code></li><li><code>T0$hkent_2026!#Pr0</code></li></ul><p><strong>Kutiladigan natija:</strong> Qaysi biri zaif va qaysi biri kuchli ekanligini izohlab, o&#39;z talqiningizdagi kuchli parolni tuzish.</p><p><strong>Yechim:</strong></p><ol><li><code>alisher2010</code> — <strong>Juda zaif</strong>. Ism va yil ishlatilgan, maxsus belgilar va katta harflar yo&#39;q. Lug&#39;at hujumi bilan bir necha soniyada topiladi.</li><li><code>qwerty123</code> — <strong>O&#39;ta zaif</strong>. Klaviaturadagi ketma-ket belgilar va sonlar. Dastlabki 10 ta eng ko&#39;p buziladigan parollar ro&#39;yxatida turadi.</li><li><code>T0$hkent_2026!#Pr0</code> — <strong>Juda kuchli</strong>. 18 ta belgi, katta-kichik harflar, raqamlar va maxsus belgilar (<code>$</code>, <code>_</code>, <code>!</code>, <code>#</code>) mavjud. Buzish uchun millionlab yillar talab etiladi. <em>O&#39;quvchi yaratgan parol namunasi:</em> <code>K!ber_8$inf#Vor!s26</code> (kamida 12 belgi, aralash tarkib).</li></ol><hr><h3 id="_2-topshiriq-fishing-xabarini-tahlil-qilish-o-rta" tabindex="-1">2-topshiriq: Fishing xabarini tahlil qilish (O&#39;rta) <a class="header-anchor" href="#_2-topshiriq-fishing-xabarini-tahlil-qilish-o-rta" aria-label="Permalink to &quot;2-topshiriq: Fishing xabarini tahlil qilish (O&#39;rta)&quot;">​</a></h3><p>O&#39;quvchiga Telegram orqali quyidagi xabar keldi:</p><blockquote><p><em>«Hurmatli foydalanuvchi! Sizning Telegram akkauntingizga shubhali kirish aniqlandi. Akkauntingiz bloklanmasligi uchun 15 daqiqa ichida quyidagi havolaga o&#39;tib kodingizni kiriting: <code>https://telegrarn-protect-uz.com/login</code>»</em></p></blockquote><p>Ushbu xabardagi 3 ta fishing belgisini aniqlang va to&#39;g&#39;ri harakat rejasini yozing.</p><p><strong>Kutiladigan natija:</strong> Shoshiltirish, soxta domen va kod talab qilish belgilarini ko&#39;rsatish hamda xabarni bloklash.</p><p><strong>Yechim:</strong></p><ol><li><strong>Soxta domen nomi:</strong> <code>telegram.org</code> o&#39;rniga <code>telegrarn-protect-uz.com</code> («m» harfi o&#39;rniga «rn» yozilgan, soxta xizmat).</li><li><strong>Shoshiltirish va qo&#39;rqitish:</strong> «15 daqiqa ichida... bloklanadi» — qurbonni o&#39;ylab ko&#39;rishga vaqt qoldirmasdan qaror qabul qildirish (ijtimoiy muhandislik).</li><li><strong>Maxfiy ma&#39;lumotni so&#39;rash:</strong> Rasmiy Telegram xizmati hech qachon shaxsiy chatda tashqi sayt havolasi orqali parol yoki kirish kodini kiritishni so&#39;ramaydi. <em>To&#39;g&#39;ri harakat:</em> Havolaga bosmaslik, botni/foydalanuvchini spam deb belgilash va darhol bloklash.</li></ol><hr><h3 id="_3-topshiriq-shaxsiy-xavfsizlik-auditini-o-tkazish-qiyin" tabindex="-1">3-topshiriq: Shaxsiy xavfsizlik auditini o&#39;tkazish (Qiyin) <a class="header-anchor" href="#_3-topshiriq-shaxsiy-xavfsizlik-auditini-o-tkazish-qiyin" aria-label="Permalink to &quot;3-topshiriq: Shaxsiy xavfsizlik auditini o&#39;tkazish (Qiyin)&quot;">​</a></h3><p>O&#39;zingizning kundalik qurilmangiz (telefon yoki noutbuk) uchun 5 banddan iborat shaxsiy kiberxavfsizlik tekshiruv ro&#39;yxatini (Checklist) tuzing va unga qat&#39;iy amal qilish qoidalarini yozing.</p><p><strong>Kutiladigan natija:</strong> Ekran qulfi, 2FA, zaxira nusxa, ilovalar ruxsati va yangilanishlarni qamrab olgan jadval.</p><p><strong>Yechim:</strong></p><table tabindex="0"><thead><tr><th>№</th><th>Tekshiruv punkti</th><th style="text-align:center;">Holat</th><th>Amaliy chora</th></tr></thead><tbody><tr><td>1</td><td>Ekran qulfi (PIN / Biometrika)</td><td style="text-align:center;">Bor</td><td>Kamida 6 xonali PIN yoki barmoq izi o&#39;rnatilgan</td></tr><tr><td>2</td><td>Asosiy akkauntlarda 2FA</td><td style="text-align:center;">Bor</td><td>Telegram va Google akkauntida ikki bosqichli tekshiruv faol</td></tr><tr><td>3</td><td>Parollar xavfsizligi</td><td style="text-align:center;">To&#39;g&#39;rilandi</td><td>Har xil saytlar uchun turli xil murakkab parollar qo&#39;yildi</td></tr><tr><td>4</td><td>Ilovalarga berilgan ruxsatlar</td><td style="text-align:center;">Tekshirildi</td><td>O&#39;yin va oddiy ilovalardan mikrafon, kontakt va joylashuv ruxsati olib tashlandi</td></tr><tr><td>5</td><td>Dasturiy yangilanishlar</td><td style="text-align:center;">Yangilangan</td><td>Operatsion tizim va brauzerning eng so&#39;nggi versiyasi o&#39;rnatilgan</td></tr></tbody></table><hr>',21))]),i("div",p,[i("h2",_,[t(r,{name:"file-text"}),a[19]||(a[19]=l(" Tezkor nazorat savollari ",-1)),a[20]||(a[20]=i("a",{class:"header-anchor",href:"#tezkor-nazorat-savollari","aria-label":'Permalink to "<Icon name="file-text" /> Tezkor nazorat savollari"'},"​",-1))]),a[21]||(a[21]=o("<ol><li><strong>Raqamli iz (Digital Footprint) nima?</strong><br><em>Javob:</em> Insonning internetdan foydalanishi davomida ortida qoldiradigan barcha faol (postlar, suratlar) va nofaol (tarix, IP, cookie) ma&#39;lumotlar to&#39;plami.</li><li><strong>2FA nima uchun faqat bitta paroldan ko&#39;ra xavfsizroq?</strong><br><em>Javob:</em> Chunki parol o&#39;g&#39;irlangan taqdirda ham, kirish uchun foydalanuvchining shaxsiy qurilmasiga keladigan 2-omil (SMS yoki ilovadagi bir martalik kod) kerak bo&#39;ladi.</li><li><strong>Fishing nima va undan qanday himoyalanish mumkin?</strong><br><em>Javob:</em> Firibgarlarning ishonchli manba nomidan soxta xabar/havola yuborib ma&#39;lumot o&#39;g&#39;irlashi. URL manzilini tekshirish, shubhali havolalarga kirmaslik va begona sahifaga parol kiritmaslik orqali himoyalaniladi.</li><li><strong>Ommaviy Wi-Fi tarmog&#39;ida nega to&#39;lov qilish xavfli?</strong><br><em>Javob:</em> Ochiq Wi-Fi shifrlanmagan bo&#39;lishi mumkin va bitta tarmoqdagi tajovuzkor uzatilayotgan ma&#39;lumotlar paketini ushlab olishi (Man-in-the-Middle) xavfi mavjud.</li></ol><hr>",2))]),i("div",T,[i("h2",j,[t(r,{name:"house"}),a[22]||(a[22]=l(" Uyga vazifa ",-1)),a[23]||(a[23]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[24]||(a[24]=i("ol",null,[i("li",null,"Ota-onangiz bilan birgalikda oilaviy Telegram va Google akkauntlarida 2FA (ikki bosqichli tekshiruv) yoqilganligini tekshiring."),i("li",null,[l("Daftaringizga kiberxavfsizlikning 5 ta oltin qoidasini yozib chiqing (batafsil shartlar "),i("code",null,"uyga-vazifa.md"),l(" da).")])],-1))])])}const C=n(h,[["render",P]]);export{B as __pageData,C as default};
